import type { ReactNode } from "react";
export { extractTextFromReactNode, getColumnLabelString } from "./column-label";

export type DataGridCellContext = {
  rowIndex: number;
};

export type DataGridColumnFilterOption = {
  value: string;
  label: string;
  detail?: string;
};

export type DataGridColumnFilters = Record<string, string[]>;

export type DataGridFunnelContext<TData> = {
  column: DataGridColumn<TData>;
  close: () => void;
};

export type DataGridFunnel<TData> = {
  id: string;
  icon?: ReactNode;
  label: string;
  isActive: boolean;
  renderWorkflow: (ctx: DataGridFunnelContext<TData>) => ReactNode;
};

export type DataGridValueType = "text" | "date";

export type DataGridCellType = "text" | "date" | "badge" | "custom";

export type DataGridCellConfig = {
  type?: DataGridCellType;
  badgeVariant?:
    | "default"
    | "secondary"
    | "destructive"
    | "outline"
    | "ghost"
    | "link";
};

export type DataGridColumn<TData> = {
  id: string;
  label: ReactNode;
  width?: number;
  /** When `date`, the grid formats `getValue` with `formatDataGridDate`. */
  valueType?: DataGridValueType;
  /** Built-in cell renderer. `custom` uses `renderCell`. */
  cell?: DataGridCellConfig;
  getValue: (row: TData) => string;
  getSortValue?: (row: TData) => string;
  renderCell?: (row: TData, ctx: DataGridCellContext) => ReactNode;
  /**
   * When true, cell is a plain container (not a row-click button).
   * Use for dropdowns, inputs, links, date pickers.
   */
  interactive?: boolean;
  funnels?: DataGridFunnel<TData>[];
  /** Whether the default list filter funnel is attached. Defaults to true. */
  filterable?: boolean;
  filterOptions?:
    | DataGridColumnFilterOption[]
    | ((rows: TData[]) => DataGridColumnFilterOption[]);
  getFilterOptions?: (
    search: string,
  ) => Promise<DataGridColumnFilterOption[]> | DataGridColumnFilterOption[];
};

export type DataGridSort = {
  columnId: string;
  direction: "asc" | "desc";
} | null;

export type DataGridViewState = {
  search: string;
  sort: DataGridSort;
  filters: DataGridColumnFilters;
};

export const DEFAULT_DATA_GRID_VIEW_STATE: DataGridViewState = {
  search: "",
  sort: null,
  filters: {},
};

export const DEFAULT_COLUMN_WIDTH = 220;
export const MIN_COLUMN_WIDTH = 64;

import type { ReactNode } from "react";

export function extractTextFromReactNode(node: ReactNode): string {
  if (node === null || node === undefined || typeof node === "boolean") {
    return "";
  }
  if (typeof node === "string" || typeof node === "number") {
    return String(node);
  }
  if (Array.isArray(node)) {
    return node.map(extractTextFromReactNode).join(" ").trim();
  }
  if (typeof node === "object" && "props" in node && node.props) {
    const children = (node.props as { children?: ReactNode }).children;
    return extractTextFromReactNode(children);
  }
  return "";
}

export function getColumnLabelString(column: {
  id: string;
  label: ReactNode;
}): string {
  const text = extractTextFromReactNode(column.label).trim();
  return text || column.id;
}

import { compareDataGridSortValues } from "./modules/sort/compare-data-grid-sort-values";
import { getDataGridColumnDisplayValue } from "./modules/cells/get-data-grid-cell-value";
import { isSerialNumberColumn } from "./modules/cells/serial-number-column";
import type { DataGridColumn, DataGridViewState } from "./types";

/** Sort (and optional client search/column filters) apply only to rows already loaded in memory. */
export function applyDataGridView<TData>(
  rows: TData[],
  columns: DataGridColumn<TData>[],
  viewState: DataGridViewState,
  options?: {
    skipClientSearch?: boolean;
    skipClientFilters?: boolean;
    skipClientSort?: boolean;
  },
) {
  const searchTerm = viewState.search.trim().toLowerCase();
  let result = rows;

  if (searchTerm && !options?.skipClientSearch) {
    result = result.filter((row) =>
      columns.some((column) => {
        if (isSerialNumberColumn(column.id)) {
          return false;
        }

        return getDataGridColumnDisplayValue(column, row)
          .toLowerCase()
          .includes(searchTerm);
      }),
    );
  }

  if (viewState.filters && !options?.skipClientFilters) {
    const activeFilterEntries = Object.entries(viewState.filters).filter(
      ([_, values]) => values && values.length > 0,
    );

    if (activeFilterEntries.length > 0) {
      result = result.filter((row) =>
        activeFilterEntries.every(([columnId, allowedValues]) => {
          const targetColumn = columns.find((col) => col.id === columnId);
          if (!targetColumn) {
            return true;
          }
          const cellValue = targetColumn.getValue(row);
          return allowedValues.includes(cellValue);
        }),
      );
    }
  }

  if (viewState.sort) {
    const sortColumn = columns.find(
      (column) => column.id === viewState.sort?.columnId,
    );
    const skipClientSort =
      Boolean(options?.skipClientSort) && !sortColumn?.getSortValue;

    if (sortColumn && !skipClientSort) {
      const direction = viewState.sort.direction === "asc" ? 1 : -1;

      if (isSerialNumberColumn(sortColumn.id)) {
        const indexByRow = new Map(result.map((row, index) => [row, index]));
        result = [...result].sort(
          (left, right) =>
            ((indexByRow.get(left) ?? 0) - (indexByRow.get(right) ?? 0)) *
            direction,
        );
      } else {
        result = [...result].sort((left, right) => {
          const leftValue =
            sortColumn.getSortValue?.(left) ?? sortColumn.getValue(left);
          const rightValue =
            sortColumn.getSortValue?.(right) ?? sortColumn.getValue(right);
          return compareDataGridSortValues(leftValue, rightValue) * direction;
        });
      }
    }
  }

  return result;
}

"use client";

import {
  useCallback,
  useEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";
import { Skeleton } from "@/components/ui/skeleton";
import { cn } from "@/lib/utils";
import { DataGridVirtualizedRows } from "./data-grid-virtualized-rows";
import { DataGridFunnelTrigger } from "./data-grid-funnel-trigger";
import { renderDataGridCell } from "./modules/cells/render-data-grid-cell";
import { clampColumnWidth } from "./modules/resize/clamp-column-width";
import { useColumnResize } from "./modules/resize/use-column-resize";
import {
  DEFAULT_COLUMN_WIDTH,
  type DataGridColumn,
} from "./types";

const SKELETON_ROWS = [
  "skeleton-1",
  "skeleton-2",
  "skeleton-3",
  "skeleton-4",
  "skeleton-5",
  "skeleton-6",
  "skeleton-7",
  "skeleton-8",
  "skeleton-9",
  "skeleton-10",
];

export type DataGridProps<TData> = {
  tableId?: string;
  columns: DataGridColumn<TData>[];
  rows: TData[];
  pinnedColumnIds: string[];
  getRowId: (row: TData) => string;
  isLoading?: boolean;
  isFetchingNextPage?: boolean;
  onRowClick?: (row: TData) => void;
  emptyMessage?: string;
  className?: string;
  onScrollContainerRef?: (element: HTMLDivElement | null) => void;
  scrollEndRef?: React.Ref<HTMLDivElement>;
  scrollVertically?: boolean;
  virtualized?: boolean;
  compact?: boolean;
  columnWidths?: Record<string, number>;
  onColumnWidthChange?: (columnId: string, width: number) => void;
  rowHoverActions?: (row: TData) => ReactNode;
};

export function DataGrid<TData>({
  tableId: _tableId,
  columns,
  rows,
  pinnedColumnIds,
  getRowId,
  isLoading = false,
  isFetchingNextPage = false,
  onRowClick,
  emptyMessage = "No results.",
  className,
  onScrollContainerRef,
  scrollEndRef,
  scrollVertically = true,
  virtualized = true,
  compact = false,
  columnWidths: controlledColumnWidths,
  onColumnWidthChange,
  rowHoverActions,
}: DataGridProps<TData>) {
  const parentRef = useRef<HTMLDivElement | null>(null);
  const [scrollElement, setScrollElement] = useState<HTMLDivElement | null>(
    null,
  );
  const [containerWidth, setContainerWidth] = useState(0);
  const [uncontrolledWidths, setUncontrolledWidths] = useState<
    Record<string, number>
  >({});

  const isControlled = controlledColumnWidths !== undefined;
  const storedWidths = isControlled
    ? controlledColumnWidths
    : uncontrolledWidths;

  const getBaseWidth = useCallback(
    (column: DataGridColumn<TData>) => {
      const stored = storedWidths[column.id];
      if (typeof stored === "number" && Number.isFinite(stored)) {
        return clampColumnWidth(stored);
      }
      return clampColumnWidth(column.width ?? DEFAULT_COLUMN_WIDTH);
    },
    [storedWidths],
  );

  const {
    resizeDraft,
    isColumnResizing,
    handleResizePointerDown,
    handleResizePointerMove,
    handleResizePointerUp,
  } = useColumnResize<TData>({
    getBaseWidth,
    isControlled,
    onColumnWidthChange,
    setUncontrolledWidths,
  });

  const estimatedRowHeight = compact ? 32 : 40;
  const headerCellClassName = compact
    ? "relative border-r bg-background px-0 py-0 font-normal text-[11px] text-muted-foreground last:border-r-0"
    : "relative border-r bg-background px-3 py-2 font-normal text-[11px] text-muted-foreground last:border-r-0";
  const bodyCellClassName = compact
    ? "relative z-0 flex min-h-8 min-w-0 items-center border-r bg-background px-0 py-0 last:border-r-0"
    : cn(
        "relative z-0 flex min-h-10 min-w-0 border-r bg-background px-3 py-2 last:border-r-0",
        virtualized ? "items-center" : "items-start",
      );

  const displayWidths = columns.map((column) => {
    if (resizeDraft?.columnId === column.id) {
      return clampColumnWidth(resizeDraft.width);
    }
    return getBaseWidth(column);
  });

  const totalColumnWidth = displayWidths.reduce(
    (total, width) => total + width,
    0,
  );

  const contentWidth = totalColumnWidth;
  const displayTotalWidth = Math.max(containerWidth, totalColumnWidth);

  useEffect(() => {
    const element = scrollElement ?? parentRef.current;
    if (!element) {
      return;
    }

    const updateWidth = () => {
      setContainerWidth(element.clientWidth);
    };

    updateWidth();

    const observer = new ResizeObserver(() => {
      updateWidth();
    });

    observer.observe(element);
    return () => observer.disconnect();
  }, [scrollElement]);

  useEffect(() => {
    if (!isColumnResizing) {
      return;
    }

    document.body.classList.add("data-grid-column-resizing");

    return () => {
      document.body.classList.remove("data-grid-column-resizing");
    };
  }, [isColumnResizing]);

  const pinnedColumnIdSet = new Set(pinnedColumnIds);
  const pinnedOffsets = (() => {
    const offsets = new Map<string, number>();
    let left = 0;

    for (const [index, column] of columns.entries()) {
      if (!pinnedColumnIdSet.has(column.id)) {
        continue;
      }

      offsets.set(column.id, left);
      left += displayWidths[index] ?? DEFAULT_COLUMN_WIDTH;
    }

    return offsets;
  })();

  const gridTemplateColumns = displayWidths
    .map((width) => `${width}px`)
    .join(" ");

  const renderRowOverlay = rowHoverActions
    ? (row: TData) => (
        <div className="pointer-events-none absolute inset-y-0 right-0 z-40 flex items-center pr-2 opacity-0 transition-opacity group-hover:pointer-events-auto group-hover:opacity-100 group-focus-within:pointer-events-auto group-focus-within:opacity-100">
          <div
            className="pointer-events-auto flex items-center gap-1 rounded-md border bg-background/95 p-1 shadow-sm"
            onClick={(event) => event.stopPropagation()}
            onPointerDown={(event) => event.stopPropagation()}
          >
            {rowHoverActions(row)}
          </div>
        </div>
      )
    : undefined;

  const renderRowCells = (row: TData, rowIndex: number) =>
    columns.map((column) => {
      const content = renderDataGridCell(column, row, rowIndex);

      const cellClassName = cn(
        bodyCellClassName,
        !compact && "min-h-10",
        pinnedOffsets.has(column.id) &&
          "sticky z-30 bg-background shadow-[1px_0_0_var(--border)]",
      );

      if (column.interactive || !onRowClick) {
        return (
          <div
            key={column.id}
            className={cn(
              cellClassName,
              onRowClick && !column.interactive && "group-hover:bg-muted/40",
              pinnedOffsets.has(column.id) &&
                onRowClick &&
                "group-hover:bg-muted",
            )}
            style={getPinnedStyle(column.id, pinnedOffsets)}
          >
            {content}
          </div>
        );
      }

      return (
        <button
          key={column.id}
          type="button"
          className={cn(
            cellClassName,
            "text-left group-hover:bg-muted/40 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
            pinnedOffsets.has(column.id) && "group-hover:bg-muted",
          )}
          style={getPinnedStyle(column.id, pinnedOffsets)}
          onClick={() => onRowClick(row)}
        >
          {content}
        </button>
      );
    });

  const onScrollContainerRefRef = useRef(onScrollContainerRef);
  onScrollContainerRefRef.current = onScrollContainerRef;

  const setScrollContainerRef = useCallback((element: HTMLDivElement | null) => {
    parentRef.current = element;
    setScrollElement(element);
    onScrollContainerRefRef.current?.(element);
  }, []);

  if (columns.length === 0 && !isLoading) {
    return (
      <div
        className={cn(
          "grid min-h-80 place-items-center text-center text-muted-foreground text-sm",
          className,
        )}
      >
        No columns are visible. Open Fields to show at least one column.
      </div>
    );
  }

  return (
    <div
      className={cn(
        virtualized
          ? "flex min-h-0 flex-1 flex-col overflow-hidden"
          : "flex flex-col",
        className,
      )}
    >
      <div
        ref={setScrollContainerRef}
        className={cn(
          virtualized ? "min-h-0 flex-1" : "w-full",
          scrollVertically
            ? "overflow-auto"
            : "overflow-x-auto overflow-y-visible",
        )}
      >
        <div
          className={cn(
            "isolate flex flex-col bg-background",
            totalColumnWidth > containerWidth && "min-w-max",
          )}
          style={{ width: displayTotalWidth }}
        >
          <div
            className="sticky top-0 z-50 grid border-b bg-background shadow-[0_1px_0_var(--border)]"
            style={{ gridTemplateColumns, width: contentWidth }}
          >
            {columns.map((column) => {
              return (
                <div
                  key={column.id}
                  className={cn(
                    headerCellClassName,
                    pinnedOffsets.has(column.id) &&
                      "sticky z-[60] shadow-[1px_0_0_var(--border)]",
                  )}
                  style={getPinnedStyle(column.id, pinnedOffsets)}
                >
                  <div className="flex min-w-0 flex-1 items-center justify-between">
                    <span className="line-clamp-1">{column.label}</span>
                    {column.funnels && column.funnels.length > 0 ? (
                      <div className="flex items-center gap-0.5">
                        {column.funnels.map((funnel) => (
                          <DataGridFunnelTrigger
                            key={funnel.id}
                            column={column}
                            funnel={funnel}
                          />
                        ))}
                      </div>
                    ) : null}
                  </div>
                  <div
                    aria-hidden
                    className="absolute top-0 right-0 z-[70] h-full w-1 cursor-col-resize touch-none select-none hover:bg-primary/30"
                    onPointerDown={(event) =>
                      handleResizePointerDown(event, column)
                    }
                    onPointerMove={handleResizePointerMove}
                    onPointerUp={handleResizePointerUp}
                    onPointerCancel={handleResizePointerUp}
                  />
                </div>
              );
            })}
          </div>

          {isLoading ? (
            <div className="grid gap-2 p-4">
              {SKELETON_ROWS.map((id) => (
                <Skeleton key={id} className="h-10 w-full" />
              ))}
              {scrollEndRef ? (
                <div
                  ref={scrollEndRef}
                  className="h-4 w-full bg-transparent"
                  aria-hidden
                />
              ) : null}
            </div>
          ) : rows.length === 0 ? (
            <div className="grid min-h-80 place-items-center text-center text-muted-foreground text-sm">
              {emptyMessage}
            </div>
          ) : virtualized ? (
            <DataGridVirtualizedRows
              rows={rows}
              getRowId={getRowId}
              scrollElement={scrollElement}
              gridTemplateColumns={gridTemplateColumns}
              contentWidth={contentWidth}
              estimatedRowHeight={estimatedRowHeight}
              compact={compact}
              scrollEndRef={scrollEndRef}
              renderRowCells={renderRowCells}
              renderRowOverlay={renderRowOverlay}
            />
          ) : (
            <div className="relative" style={{ width: contentWidth }}>
              {rows.map((row, rowIndex) => (
                <div
                  key={getRowId(row)}
                  className={cn(
                    "group isolate grid overflow-hidden border-b border-border text-left font-normal text-[13px] transition-colors hover:bg-muted/40",
                    compact ? "min-h-8" : "min-h-10",
                  )}
                  style={{
                    gridTemplateColumns,
                    width: contentWidth,
                  }}
                >
                  {renderRowCells(row, rowIndex)}
                  {renderRowOverlay?.(row)}
                </div>
              ))}
              {scrollEndRef ? (
                <div
                  ref={scrollEndRef}
                  className="h-4 w-full bg-transparent"
                  aria-hidden
                />
              ) : null}
            </div>
          )}
        </div>
      </div>

      {isFetchingNextPage ? (
        <div className="border-t px-4 py-2 text-muted-foreground text-xs">
          Loading more...
        </div>
      ) : null}
    </div>
  );
}

function getPinnedStyle(
  columnId: string,
  pinnedOffsets: Map<string, number>,
): CSSProperties | undefined {
  const left = pinnedOffsets.get(columnId);

  if (left === undefined) {
    return undefined;
  }

  return { left };
}

"use client";

import { type CSSProperties, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { applyDataGridView } from "./apply-data-grid-view";
import { DataGrid } from "./data-grid";
import { DataGridToolbar } from "./modules/toolbar/data-grid-toolbar";
import { exportDataGridCsv } from "./modules/export/export-data-grid";
import { createSerialNumberColumn } from "./modules/cells/serial-number-column";
import type {
  DataGridColumn,
  DataGridColumnFilters,
  DataGridSort,
} from "./types";
import { useDataGridColumns } from "./modules/fields/use-data-grid-columns";
import { useDataGridFunnels } from "./modules/filters/use-data-grid-funnels";
import {
  type DataGridInitialBehavior,
  useDataGridInitialBehavior,
} from "./modules/initial-behavior/use-data-grid-initial-behavior";
import { readDataGridPersistedState } from "./modules/persistence/use-data-grid-persistence";
import { useDataGridViewportHeight } from "./modules/viewport/use-data-grid-viewport-height";
import { DATA_GRID_SEARCH_DEBOUNCE_MS } from "./modules/search/use-debounced-callback";
import { useDebouncedSearch } from "./modules/search/use-debounced-search";

export type DataGridViewProps<TData> = {
  tableId: string;
  columns: DataGridColumn<TData>[];
  rows: TData[];
  getRowId: (row: TData) => string;
  isLoading?: boolean;
  isFetchingNextPage?: boolean;
  onRowClick?: (row: TData) => void;
  emptyMessage?: string;
  searchPlaceholder?: string;
  exportFilename?: string;
  toolbarActions?: ReactNode;
  searchActions?: ReactNode;
  /**
   * Debounced (~250ms) search callback for API-backed lists.
   * When set, client-side search is skipped.
   */
  onSearch?: (search: string) => void;
  searchDebounceMs?: number;
  fillViewport?: boolean;
  className?: string;
  onScrollContainerRef?: (element: HTMLDivElement | null) => void;
  scrollEndRef?: React.Ref<HTMLDivElement>;
  serverSearch?: boolean;
  onServerSearchChange?: (search: string) => void;
  columnFilters?: DataGridColumnFilters;
  onColumnFiltersChange?: (filters: DataGridColumnFilters) => void;
  onServerFilterChange?: (filters: DataGridColumnFilters) => void;
  sort?: DataGridSort;
  onSortChange?: (sort: DataGridSort) => void;
  initialBehavior?: DataGridInitialBehavior;
  persist?: boolean;
  persistViewState?: boolean;
  rowHoverActions?: (row: TData) => ReactNode;
  virtualized?: boolean;
  compact?: boolean;
};

export function DataGridView<TData>({
  tableId,
  columns,
  rows,
  getRowId,
  isLoading = false,
  isFetchingNextPage = false,
  onRowClick,
  emptyMessage = "No results.",
  searchPlaceholder,
  exportFilename,
  toolbarActions,
  searchActions,
  onSearch,
  searchDebounceMs = DATA_GRID_SEARCH_DEBOUNCE_MS,
  fillViewport = false,
  className,
  onScrollContainerRef,
  scrollEndRef,
  serverSearch = false,
  onServerSearchChange,
  columnFilters,
  onColumnFiltersChange,
  onServerFilterChange,
  sort,
  onSortChange,
  initialBehavior,
  persist = true,
  persistViewState = false,
  rowHoverActions,
  virtualized = true,
  compact = false,
}: DataGridViewProps<TData>) {
  const storedView = persistViewState
    ? readDataGridPersistedState(tableId)?.view
    : undefined;
  const columnsWithSerial = [createSerialNumberColumn<TData>(), ...columns];
  const {
    search,
    setSearch,
    sort: internalSort,
    setSort: setInternalSort,
    columnFilters: internalFilters,
    setColumnFilters: setInternalFilters,
  } = useDataGridInitialBehavior({
    search: storedView?.search ?? initialBehavior?.search,
    sort: storedView?.sort ?? initialBehavior?.sort,
    filters: storedView?.filters ?? initialBehavior?.filters,
  });
  const searchHandler = onSearch ?? onServerSearchChange;
  const notifyServerSearch = useDebouncedSearch(
    searchHandler,
    searchDebounceMs,
  );
  const { sentinelRef, layout, estimatedHeight } =
    useDataGridViewportHeight(fillViewport);

  const activeFilters = columnFilters ?? internalFilters;
  const activeSort = sort !== undefined ? sort : internalSort;
  const skipClientSearch = serverSearch || Boolean(searchHandler);
  const skipClientSort = Boolean(onSortChange);
  const skipClientFilters =
    Boolean(onServerFilterChange) || Boolean(onColumnFiltersChange);

  const {
    columnOrder,
    columnWidths,
    moveColumn,
    orderedColumns,
    pinnedColumnIds,
    setColumnWidth,
    updatePinnedColumnIds,
    updateVisibleColumnIds,
    visibleColumnIds,
  } = useDataGridColumns({
    tableId,
    columns: columnsWithSerial,
    persist,
    viewState: persistViewState
      ? {
          search,
          sort: activeSort,
          filters: activeFilters,
        }
      : undefined,
  });

  function handleSearchChange(nextSearch: string) {
    setSearch(nextSearch);
    if (skipClientSearch) {
      notifyServerSearch(nextSearch);
    }
  }

  function handleSortChange(nextSort: DataGridSort) {
    if (onSortChange) {
      onSortChange(nextSort);
      return;
    }
    setInternalSort(nextSort);
  }

  function handleClearFilters() {
    if (onColumnFiltersChange) {
      onColumnFiltersChange({});
    } else {
      setInternalFilters({});
    }
    onServerFilterChange?.({});
  }

  const handleAllFiltersChange = (nextFilters: DataGridColumnFilters) => {
    if (onColumnFiltersChange) {
      onColumnFiltersChange(nextFilters);
    } else {
      setInternalFilters(nextFilters);
    }
    onServerFilterChange?.(nextFilters);
  };

  const visibleRows = applyDataGridView(
    rows,
    orderedColumns,
    { search, sort: activeSort, filters: activeFilters },
    {
      skipClientSearch,
      skipClientFilters,
      skipClientSort,
    },
  );

  const { columns: funneledColumns } = useDataGridFunnels({
    columns: orderedColumns,
    rows,
    columnFilters: activeFilters,
    onColumnFiltersChange: handleAllFiltersChange,
  });

  function handleExportCsv() {
    const visibleColumnIdSet = new Set(visibleColumnIds);
    exportDataGridCsv({
      filename: exportFilename ?? tableId,
      columns: orderedColumns.filter((column) =>
        visibleColumnIdSet.has(column.id),
      ),
      rows: visibleRows,
    });
  }

  const panelStyle = ((): CSSProperties | undefined => {
    if (!fillViewport) return undefined;

    if (layout) {
      return {
        position: "fixed",
        top: layout.top,
        left: layout.left,
        width: layout.width,
        height: layout.height,
        zIndex: 0,
      };
    }

    return {
      height: estimatedHeight,
      maxHeight: estimatedHeight,
    };
  })();

  return (
    <>
      {fillViewport ? (
        <div ref={sentinelRef} className="h-0 w-full shrink-0" aria-hidden />
      ) : null}

      {fillViewport && layout ? (
        <div
          className="w-full shrink-0"
          style={{ height: layout.height }}
          aria-hidden
        />
      ) : null}

      <div
        style={panelStyle}
        className={cn(
          "flex min-h-0 flex-col overflow-hidden bg-background",
          !fillViewport && "h-[32rem]",
          className,
        )}
      >
        <DataGridToolbar
          columns={columnsWithSerial}
          visibleColumnIds={visibleColumnIds}
          pinnedColumnIds={pinnedColumnIds}
          columnOrder={columnOrder}
          search={search}
          sort={activeSort}
          columnFilters={activeFilters}
          searchPlaceholder={searchPlaceholder}
          onSearchChange={handleSearchChange}
          onVisibleColumnIdsChange={updateVisibleColumnIds}
          onPinnedColumnIdsChange={updatePinnedColumnIds}
          onColumnMove={moveColumn}
          onSortChange={handleSortChange}
          onClearFilters={handleClearFilters}
          onExportCsv={handleExportCsv}
          toolbarActions={toolbarActions}
          searchActions={searchActions}
        />

        <DataGrid
          tableId={tableId}
          columns={funneledColumns}
          rows={visibleRows}
          pinnedColumnIds={pinnedColumnIds}
          columnWidths={columnWidths}
          onColumnWidthChange={setColumnWidth}
          getRowId={getRowId}
          isLoading={isLoading}
          isFetchingNextPage={isFetchingNextPage}
          onRowClick={onRowClick}
          emptyMessage={emptyMessage}
          onScrollContainerRef={onScrollContainerRef}
          scrollEndRef={scrollEndRef}
          scrollVertically={fillViewport || virtualized}
          virtualized={virtualized}
          compact={compact}
          rowHoverActions={rowHoverActions}
        />
      </div>
    </>
  );
}

