import { getColumnLabelString } from "../../column-label";
import type { DataGridColumn } from "../../types";
import { getDataGridColumnDisplayValue } from "../cells/get-data-grid-cell-value";
import { toCsv } from "./csv-utils";
import { downloadTextFile } from "./download-text-file";
import { sanitizeFilename } from "./sanitize-filename";

export function buildDataGridExportRows<TData>(input: {
  columns: DataGridColumn<TData>[];
  rows: TData[];
}) {
  const headers = getUniqueColumnLabels(input.columns);

  return input.rows.map((row, rowIndex) =>
    input.columns.reduce<Record<string, string>>((record, column, index) => {
      record[headers[index] ?? getColumnLabelString(column)] =
        getDataGridColumnDisplayValue(column, row, rowIndex);
      return record;
    }, {}),
  );
}

export { toCsv } from "./csv-utils";
export { downloadTextFile } from "./download-text-file";
export { sanitizeFilename } from "./sanitize-filename";

function getUniqueColumnLabels<TData>(columns: DataGridColumn<TData>[]) {
  const seen = new Map<string, number>();

  return columns.map((column) => {
    const label = getColumnLabelString(column);
    const count = seen.get(label) ?? 0;

    seen.set(label, count + 1);

    return count === 0 ? label : `${label} ${count + 1}`;
  });
}

export function exportDataGridCsv<TData>(input: {
  columns: DataGridColumn<TData>[];
  rows: TData[];
  filename: string;
}) {
  const exportRows = buildDataGridExportRows(input);
  downloadTextFile({
    filename: `${sanitizeFilename(input.filename)}.csv`,
    mimeType: "text/csv;charset=utf-8",
    contents: toCsv(exportRows),
  });
}

export function toCsv(rows: Array<Record<string, string>>) {
  if (rows.length === 0) {
    return "";
  }

  const headers = Object.keys(rows[0] ?? {});
  const lines = [
    headers.map(escapeCsvCell).join(","),
    ...rows.map((row) =>
      headers.map((header) => escapeCsvCell(row[header] ?? "")).join(","),
    ),
  ];

  return lines.join("\n");
}

export function escapeCsvCell(value: string) {
  const normalizedValue = neutralizeSpreadsheetFormula(
    value.replace(/\r?\n/g, "\n"),
  );

  if (
    normalizedValue.includes(",") ||
    normalizedValue.includes('"') ||
    normalizedValue.includes("\n")
  ) {
    return `"${normalizedValue.replaceAll('"', '""')}"`;
  }

  return normalizedValue;
}

export function neutralizeSpreadsheetFormula(value: string) {
  return /^[=+\-@\t\r]/.test(value) ? `'${value}` : value;
}

export function downloadTextFile(input: {
  filename: string;
  mimeType: string;
  contents: string;
}) {
  const bom = "\uFEFF";
  const blob = new Blob([bom + input.contents], { type: input.mimeType });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");

  anchor.href = url;
  anchor.download = input.filename;
  anchor.click();
  URL.revokeObjectURL(url);
}

export function sanitizeFilename(value: string) {
  return (
    value
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "") || "export"
  );
}

"use client";

import { useRef, useState, type PointerEvent as ReactPointerEvent } from "react";
import type { DataGridColumn } from "../../types";
import { clampColumnWidth } from "./clamp-column-width";

export type ResizeDraft = {
  columnId: string;
  startX: number;
  startWidth: number;
  width: number;
};

export type UseColumnResizeInput<TData> = {
  getBaseWidth: (column: DataGridColumn<TData>) => number;
  isControlled: boolean;
  onColumnWidthChange?: (columnId: string, width: number) => void;
  setUncontrolledWidths: (
    update: (current: Record<string, number>) => Record<string, number>,
  ) => void;
};

export function useColumnResize<TData>({
  getBaseWidth,
  isControlled,
  onColumnWidthChange,
  setUncontrolledWidths,
}: UseColumnResizeInput<TData>) {
  const [resizeDraft, setResizeDraft] = useState<ResizeDraft | null>(null);
  const resizeDraftRef = useRef<ResizeDraft | null>(null);

  function commitWidth(columnId: string, width: number) {
    const nextWidth = clampColumnWidth(width);
    if (onColumnWidthChange) {
      onColumnWidthChange(columnId, nextWidth);
      return;
    }
    if (!isControlled) {
      setUncontrolledWidths((current) => ({
        ...current,
        [columnId]: nextWidth,
      }));
    }
  }

  function endResize(event: PointerEvent) {
    const draft = resizeDraftRef.current;
    if (!draft) {
      return;
    }

    const target = event.target as Element | null;
    if (target && "releasePointerCapture" in target) {
      try {
        (target as Element).releasePointerCapture(event.pointerId);
      } catch {
        // Pointer may already be released.
      }
    }

    commitWidth(draft.columnId, draft.width);
    resizeDraftRef.current = null;
    setResizeDraft(null);
  }

  function handleResizePointerDown(
    event: ReactPointerEvent<HTMLDivElement>,
    column: DataGridColumn<TData>,
  ) {
    event.preventDefault();
    event.stopPropagation();

    const startWidth = getBaseWidth(column);
    const draft: ResizeDraft = {
      columnId: column.id,
      startX: event.clientX,
      startWidth,
      width: startWidth,
    };
    resizeDraftRef.current = draft;
    setResizeDraft(draft);

    event.currentTarget.setPointerCapture(event.pointerId);
  }

  function handleResizePointerMove(event: ReactPointerEvent<HTMLDivElement>) {
    const draft = resizeDraftRef.current;
    if (!draft) {
      return;
    }

    const nextWidth = clampColumnWidth(
      draft.startWidth + (event.clientX - draft.startX),
    );
    const nextDraft = { ...draft, width: nextWidth };
    resizeDraftRef.current = nextDraft;
    setResizeDraft(nextDraft);
  }

  function handleResizePointerUp(event: ReactPointerEvent<HTMLDivElement>) {
    endResize(event.nativeEvent);
  }

  return {
    resizeDraft,
    isColumnResizing: resizeDraft !== null,
    handleResizePointerDown,
    handleResizePointerMove,
    handleResizePointerUp,
  };
}

import { MIN_COLUMN_WIDTH } from "../../types";

export function clampColumnWidth(width: number) {
  return Math.max(MIN_COLUMN_WIDTH, Math.round(width));
}

"use client";

import { useCallback, useMemo, useState } from "react";
import type { DataGridColumnFilters } from "../../types";

function omitColumnFilter(
  filters: DataGridColumnFilters,
  columnId: string,
): DataGridColumnFilters {
  const next = { ...filters };
  delete next[columnId];
  return next;
}

export function useDataGridColumnFilters(
  initialFilters: DataGridColumnFilters = {},
) {
  const [columnFilters, setColumnFilters] =
    useState<DataGridColumnFilters>(initialFilters);

  const setColumnFilter = useCallback(
    (columnId: string, selectedValues: string[]) => {
      setColumnFilters((current) => {
        if (selectedValues.length === 0) {
          return omitColumnFilter(current, columnId);
        }
        return {
          ...current,
          [columnId]: selectedValues,
        };
      });
    },
    [],
  );

  const clearColumnFilter = useCallback((columnId: string) => {
    setColumnFilters((current) => omitColumnFilter(current, columnId));
  }, []);

  const clearAllFilters = useCallback(() => {
    setColumnFilters({});
  }, []);

  const activeFilterCount = useMemo(() => {
    return Object.keys(columnFilters).filter(
      (key) => (columnFilters[key]?.length ?? 0) > 0,
    ).length;
  }, [columnFilters]);

  const hasActiveFilters = activeFilterCount > 0;

  const toQueryParams = useCallback(() => {
    if (!hasActiveFilters) {
      return {};
    }
    return {
      filters: JSON.stringify(columnFilters),
    };
  }, [columnFilters, hasActiveFilters]);

  return {
    columnFilters,
    setColumnFilters,
    setColumnFilter,
    clearColumnFilter,
    clearAllFilters,
    hasActiveFilters,
    activeFilterCount,
    toQueryParams,
  };
}

