"use client";

import { useMemo } from "react";
import { createFilterFunnel } from "./funnels/filter-funnel-factories";
import { isSerialNumberColumn } from "../cells/serial-number-column";
import type { DataGridColumn, DataGridColumnFilters } from "../../types";

export type UseDataGridFunnelsOptions<TData> = {
  columns: DataGridColumn<TData>[];
  rows: TData[];
  columnFilters: DataGridColumnFilters;
  onColumnFiltersChange: (filters: DataGridColumnFilters) => void;
};

export function useDataGridFunnels<TData>({
  columns,
  rows,
  columnFilters = {},
  onColumnFiltersChange,
}: UseDataGridFunnelsOptions<TData>) {
  const funneledColumns = useMemo(() => {
    return columns.map((column) => {
      const existingFunnels = column.funnels ?? [];

      const isFilterable =
        column.filterable !== false && !isSerialNumberColumn(column.id);

      const filterFunnelExists = existingFunnels.some(
        (funnel) => funnel.id === "filter" || funnel.id.startsWith("filter"),
      );

      const funnels = [...existingFunnels];

      if (isFilterable && !filterFunnelExists) {
        const filterValues = columnFilters[column.id] ?? [];
        const filterFunnel = createFilterFunnel<TData>({
          rows,
          selectedValues: filterValues,
          allActiveFilters: columnFilters,
          onFilterChange: (nextValues) => {
            const nextFilters = { ...columnFilters };
            if (nextValues.length === 0) {
              delete nextFilters[column.id];
            } else {
              nextFilters[column.id] = nextValues;
            }
            onColumnFiltersChange(nextFilters);
          },
        });
        funnels.push(filterFunnel);
      }

      return {
        ...column,
        funnels,
      };
    });
  }, [columns, rows, columnFilters, onColumnFiltersChange]);

  return {
    columns: funneledColumns,
  };
}

import type { DataGridColumnFilters } from "../../types";

export function serializeColumnFilters(
  filters?: DataGridColumnFilters,
): Record<string, string | undefined> {
  if (!filters) {
    return {};
  }
  const activeEntries = Object.entries(filters).filter(
    ([, values]) => values && values.length > 0,
  );
  if (activeEntries.length === 0) {
    return {};
  }
  const cleanFilters: DataGridColumnFilters = {};
  for (const [key, values] of activeEntries) {
    cleanFilters[key] = values;
  }
  return {
    filters: JSON.stringify(cleanFilters),
  };
}

import { formatDataGridDate } from "../cells/format-date";
import type {
  DataGridColumn,
  DataGridColumnFilterOption,
} from "../../types";

export function resolveFilterOptions<TData>(input: {
  column: DataGridColumn<TData>;
  rows: TData[];
  asyncOptions: DataGridColumnFilterOption[] | null;
}): DataGridColumnFilterOption[] {
  const { column, rows, asyncOptions } = input;

  if (column.getFilterOptions) {
    return asyncOptions ?? [];
  }

  if (column.filterOptions) {
    if (typeof column.filterOptions === "function") {
      return column.filterOptions(rows);
    }
    return column.filterOptions;
  }

  const uniqueValuesMap = new Map<string, string>();
  for (const row of rows) {
    const value = column.getValue(row);
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ""
    ) {
      const valueStr = String(value);
      if (!uniqueValuesMap.has(valueStr)) {
        uniqueValuesMap.set(valueStr, valueStr);
      }
    }
  }

  const sortedValues = Array.from(uniqueValuesMap.keys()).sort((a, b) =>
    a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" }),
  );

  return sortedValues.map((val) => {
    const isDate = column.valueType === "date" || column.cell?.type === "date";
    return {
      value: val,
      label: isDate ? formatDataGridDate(val) : val,
    };
  });
}

export function filterOptionsBySearch(
  options: DataGridColumnFilterOption[],
  search: string,
): DataGridColumnFilterOption[] {
  if (!search.trim()) {
    return options;
  }
  const queryTerm = search.trim().toLowerCase();
  return options.filter(
    (opt) =>
      opt.label.toLowerCase().includes(queryTerm) ||
      opt.value.toLowerCase().includes(queryTerm) ||
      (opt.detail && opt.detail.toLowerCase().includes(queryTerm)),
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { Loader2Icon, SearchIcon, XIcon } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { getColumnLabelString } from "../../../column-label";
import type {
  DataGridColumn,
  DataGridColumnFilterOption,
} from "../../../types";
import { DATA_GRID_SEARCH_DEBOUNCE_MS } from "../../search/use-debounced-callback";
import {
  filterOptionsBySearch,
  resolveFilterOptions,
} from "../resolve-filter-options";
import { FilterFunnelVirtualList } from "./filter-funnel-virtual-list";

type FilterFunnelContentProps<TData> = {
  column: DataGridColumn<TData>;
  rows: TData[];
  selectedValues: string[];
  onFilterChange: (selectedValues: string[]) => void;
  close: () => void;
  showSearch?: boolean;
};

export function FilterFunnelContent<TData>({
  column,
  rows,
  selectedValues = [],
  onFilterChange,
  close,
  showSearch = true,
}: FilterFunnelContentProps<TData>) {
  const [search, setSearch] = useState("");
  const [debouncedSearch, setDebouncedSearch] = useState("");
  const [draftSelected, setDraftSelected] = useState<string[]>(selectedValues);
  const [asyncOptions, setAsyncOptions] = useState<
    DataGridColumnFilterOption[] | null
  >(null);
  const [isLoadingAsync, setIsLoadingAsync] = useState(false);

  useEffect(() => {
    if (!column.getFilterOptions) {
      return;
    }
    const timeoutId = window.setTimeout(() => {
      setDebouncedSearch(search);
    }, DATA_GRID_SEARCH_DEBOUNCE_MS);
    return () => window.clearTimeout(timeoutId);
  }, [column.getFilterOptions, search]);

  useEffect(() => {
    if (!column.getFilterOptions) {
      setAsyncOptions(null);
      return;
    }

    let isMounted = true;
    setIsLoadingAsync(true);

    Promise.resolve(column.getFilterOptions(debouncedSearch))
      .then((opts) => {
        if (isMounted) {
          setAsyncOptions(opts);
          setIsLoadingAsync(false);
        }
      })
      .catch(() => {
        if (isMounted) {
          setAsyncOptions([]);
          setIsLoadingAsync(false);
        }
      });

    return () => {
      isMounted = false;
    };
  }, [column, debouncedSearch]);

  const resolvedOptions = useMemo<DataGridColumnFilterOption[]>(
    () => resolveFilterOptions({ column, rows, asyncOptions }),
    [asyncOptions, column, rows],
  );

  const filteredOptions = useMemo(() => {
    if (column.getFilterOptions) {
      return resolvedOptions;
    }
    return filterOptionsBySearch(resolvedOptions, search);
  }, [column.getFilterOptions, resolvedOptions, search]);

  const activeCount = selectedValues.length;
  const isFiltered = activeCount > 0;

  const allFilteredSelected =
    filteredOptions.length > 0 &&
    filteredOptions.every((opt) => draftSelected.includes(opt.value));

  function toggleSelectAll() {
    if (allFilteredSelected) {
      const valuesToRemove = new Set(filteredOptions.map((opt) => opt.value));
      setDraftSelected((prev) => prev.filter((v) => !valuesToRemove.has(v)));
    } else {
      const newValues = new Set([
        ...draftSelected,
        ...filteredOptions.map((opt) => opt.value),
      ]);
      setDraftSelected(Array.from(newValues));
    }
  }

  function toggleOption(value: string) {
    setDraftSelected((prev) =>
      prev.includes(value)
        ? prev.filter((item) => item !== value)
        : [...prev, value],
    );
  }

  function handleApply() {
    onFilterChange(draftSelected);
    close();
  }

  function handleClear() {
    setDraftSelected([]);
    onFilterChange([]);
    close();
  }

  const columnTitle = getColumnLabelString(column);

  return (
    <div className="flex flex-col gap-2">
      <div className="pb-1 text-xs font-semibold">Filter: {columnTitle}</div>

      {showSearch ? (
        <div className="relative my-1">
          <SearchIcon className="absolute top-1/2 left-2 size-3.5 -translate-y-1/2 text-muted-foreground" />
          <Input
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            placeholder={`Search ${columnTitle.toLowerCase()}...`}
            className="h-7 pr-7 pl-7 text-xs shadow-none"
          />
          {search ? (
            <button
              type="button"
              onClick={() => setSearch("")}
              className="absolute top-1/2 right-2 -translate-y-1/2 text-muted-foreground hover:text-foreground"
              aria-label="Clear search"
            >
              <XIcon className="size-3" />
            </button>
          ) : null}
        </div>
      ) : null}

      {filteredOptions.length > 0 ? (
        <div className="flex items-center justify-between border-b px-1 py-1 text-[11px] text-muted-foreground">
          <button
            type="button"
            onClick={toggleSelectAll}
            className="font-medium text-primary hover:underline"
          >
            {allFilteredSelected ? "Deselect all" : "Select all"}
          </button>
          <span>{draftSelected.length} selected</span>
        </div>
      ) : null}

      <div className="max-h-48 min-h-20 overflow-y-auto py-1">
        {isLoadingAsync ? (
          <div className="flex items-center justify-center gap-2 py-6 text-muted-foreground text-xs">
            <Loader2Icon className="size-3.5 animate-spin" />
            Loading options...
          </div>
        ) : filteredOptions.length === 0 ? (
          <div className="py-6 text-center text-muted-foreground text-xs">
            No options available.
          </div>
        ) : (
          <FilterFunnelVirtualList
            options={filteredOptions}
            draftSelected={draftSelected}
            toggleOption={toggleOption}
          />
        )}
      </div>

      <div className="mt-1 flex items-center justify-between border-t pt-2">
        <Button
          type="button"
          variant="ghost"
          size="sm"
          className="h-7 px-2 text-xs"
          onClick={handleClear}
          disabled={draftSelected.length === 0 && !isFiltered}
        >
          Clear
        </Button>
        <div className="flex gap-1.5">
          <Button
            type="button"
            variant="outline"
            size="sm"
            className="h-7 px-2.5 text-xs"
            onClick={close}
          >
            Cancel
          </Button>
          <Button
            type="button"
            size="sm"
            className="h-7 px-3 text-xs"
            onClick={handleApply}
          >
            Apply
          </Button>
        </div>
      </div>
    </div>
  );
}

