import { useEffect, useRef } from "react";

export const DATA_GRID_SEARCH_DEBOUNCE_MS = 250;

export function useDebouncedCallback<T extends (...args: never[]) => void>(
  callback: T,
  delay: number = DATA_GRID_SEARCH_DEBOUNCE_MS,
) {
  const callbackRef = useRef(callback);
  callbackRef.current = callback;
  const timeoutRef = useRef<number | null>(null);

  function debounced(...args: Parameters<T>) {
    if (timeoutRef.current !== null) {
      window.clearTimeout(timeoutRef.current);
    }
    timeoutRef.current = window.setTimeout(() => {
      callbackRef.current(...args);
    }, delay);
  }

  useEffect(() => {
    return () => {
      if (timeoutRef.current !== null) {
        window.clearTimeout(timeoutRef.current);
      }
    };
  }, []);

  return debounced;
}

import {
  DATA_GRID_SEARCH_DEBOUNCE_MS,
  useDebouncedCallback,
} from "./use-debounced-callback";

export function useDebouncedSearch(
  onSearch: ((search: string) => void) | undefined,
  delay: number = DATA_GRID_SEARCH_DEBOUNCE_MS,
) {
  return useDebouncedCallback((nextSearch: string) => {
    onSearch?.(nextSearch.trim());
  }, delay);
}

import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { getDataGridColumnDisplayValue } from "./get-data-grid-cell-value";
import type { DataGridCellContext, DataGridColumn } from "../../types";

export function renderDataGridCell<TData>(
  column: DataGridColumn<TData>,
  row: TData,
  rowIndex: number,
) {
  const cellCtx: DataGridCellContext = { rowIndex };
  if (column.renderCell) {
    return column.renderCell(row, cellCtx);
  }

  const value = getDataGridColumnDisplayValue(column, row, rowIndex);
  const cellType = column.cell?.type ?? (column.valueType === "date" ? "date" : "text");

  if (cellType === "badge") {
    return (
      <Badge variant={column.cell?.badgeVariant ?? "outline"} className="capitalize">
        {value}
      </Badge>
    );
  }

  return (
    <span
      className={cn(
        "truncate font-normal",
        value === "—" && "text-muted-foreground",
      )}
      title={value}
    >
      {value}
    </span>
  );
}

import { formatDataGridDate } from "./format-date";
import {
  getSerialNumberValue,
  isSerialNumberColumn,
} from "./serial-number-column";
import type { DataGridColumn } from "../../types";

export function getDataGridColumnDisplayValue<TData>(
  column: DataGridColumn<TData>,
  row: TData,
  rowIndex?: number,
) {
  if (isSerialNumberColumn(column.id) && rowIndex !== undefined) {
    return getSerialNumberValue(rowIndex);
  }

  const raw = column.getValue(row);
  const isDate =
    column.valueType === "date" || column.cell?.type === "date";

  if (isDate) {
    return formatDataGridDate(raw);
  }

  return raw;
}

export function formatDataGridDate(value: string, locale?: string) {
  const trimmed = value.trim();
  if (!trimmed || trimmed === "—") {
    return "—";
  }

  const timestamp = Date.parse(
    trimmed.length === 10 ? `${trimmed}T00:00:00` : trimmed,
  );

  if (Number.isNaN(timestamp)) {
    return value;
  }

  return new Intl.DateTimeFormat(locale, {
    year: "numeric",
    month: "short",
    day: "numeric",
  }).format(new Date(timestamp));
}

