"use client";

import { useState, type ReactNode } from "react";
import { cn } from "@/lib/utils";

export type EditableCellEditorProps<TValue> = {
  value: TValue;
  commit: (nextValue: TValue) => void;
  cancel: () => void;
};

export function EditableCell<TValue>({
  value,
  onCommit,
  renderEditor,
  renderDisplay,
  className,
}: {
  value: TValue;
  onCommit: (value: TValue) => void;
  /** Any component with its own internal state — input, textarea, select, date picker, etc. Call `commit` to save and close, `cancel` to discard and close. */
  renderEditor: (props: EditableCellEditorProps<TValue>) => ReactNode;
  /** Defaults to rendering `value` as-is. */
  renderDisplay?: (value: TValue) => ReactNode;
  className?: string;
}) {
  const [editing, setEditing] = useState(false);

  function commit(nextValue: TValue) {
    if (nextValue !== value) {
      onCommit(nextValue);
    }
    setEditing(false);
  }

  function cancel() {
    setEditing(false);
  }

  if (editing) {
    return <>{renderEditor({ value, commit, cancel })}</>;
  }

  return (
    <button
      type="button"
      className={cn(
        "h-7 w-full truncate rounded-sm px-1 text-left text-[13px] hover:bg-muted",
        className,
      )}
      onClick={() => setEditing(true)}
    >
      {renderDisplay ? renderDisplay(value) : (value as ReactNode)}
    </button>
  );
}

/** Text-input editor for `EditableCell`'s `renderEditor` — the common case of editing a single line of text. */
export function TextEditorInput({
  value,
  commit,
  cancel,
}: EditableCellEditorProps<string>) {
  const [draft, setDraft] = useState(value);

  return (
    <input
      autoFocus
      value={draft}
      onChange={(event) => setDraft(event.currentTarget.value)}
      onBlur={() => commit(draft.trim() ? draft : value)}
      onKeyDown={(event) => {
        if (event.key === "Enter") {
          event.currentTarget.blur();
        }
        if (event.key === "Escape") {
          cancel();
        }
      }}
      className="h-7 w-full min-w-0 rounded-sm bg-background px-1 text-[13px] outline-none ring-1 ring-ring"
    />
  );
}

import type { DataGridColumnFilters, DataGridSort } from "../../types";

export type DataGridColumnLayoutState = {
  visibleColumnIds: string[];
  columnOrder: string[];
  pinnedColumnIds: string[];
  columnWidths: Record<string, number>;
};

export type DataGridPersistedState = {
  layout: DataGridColumnLayoutState;
  view?: {
    search: string;
    sort: DataGridSort;
    filters: DataGridColumnFilters;
  };
};

export const EMPTY_DATA_GRID_LAYOUT: DataGridColumnLayoutState = {
  visibleColumnIds: [],
  columnOrder: [],
  pinnedColumnIds: [],
  columnWidths: {},
};

export function dataGridStorageKey(tableId: string) {
  return `data-grid:${tableId}`;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function parseStringArray(value: unknown): string[] {
  if (!Array.isArray(value)) {
    return [];
  }
  return value.filter((item): item is string => typeof item === "string");
}

function parseWidths(value: unknown): Record<string, number> {
  if (!isRecord(value)) {
    return {};
  }
  const widths: Record<string, number> = {};
  for (const [key, width] of Object.entries(value)) {
    if (typeof width === "number" && Number.isFinite(width)) {
      widths[key] = width;
    }
  }
  return widths;
}

function parseSort(value: unknown): DataGridSort {
  if (value === null) {
    return null;
  }
  if (
    isRecord(value) &&
    typeof value.columnId === "string" &&
    (value.direction === "asc" || value.direction === "desc")
  ) {
    return {
      columnId: value.columnId,
      direction: value.direction,
    };
  }
  return null;
}

function parseFilters(value: unknown): DataGridColumnFilters {
  if (!isRecord(value)) {
    return {};
  }
  const filters: DataGridColumnFilters = {};
  for (const [key, values] of Object.entries(value)) {
    const next = parseStringArray(values);
    if (next.length > 0) {
      filters[key] = next;
    }
  }
  return filters;
}

export function readDataGridPersistedState(
  tableId: string,
): DataGridPersistedState | null {
  if (typeof window === "undefined") {
    return null;
  }

  try {
    const raw = window.localStorage.getItem(dataGridStorageKey(tableId));
    if (!raw) {
      return null;
    }
    const parsed: unknown = JSON.parse(raw);
    if (!isRecord(parsed)) {
      return null;
    }

    const layoutSource = isRecord(parsed.layout) ? parsed.layout : parsed;

    return {
      layout: {
        visibleColumnIds: parseStringArray(layoutSource.visibleColumnIds),
        columnOrder: parseStringArray(layoutSource.columnOrder),
        pinnedColumnIds: parseStringArray(layoutSource.pinnedColumnIds),
        columnWidths: parseWidths(layoutSource.columnWidths),
      },
      view: isRecord(parsed.view)
        ? {
            search:
              typeof parsed.view.search === "string" ? parsed.view.search : "",
            sort: parseSort(parsed.view.sort),
            filters: parseFilters(parsed.view.filters),
          }
        : undefined,
    };
  } catch {
    return null;
  }
}

export function writeDataGridPersistedState(
  tableId: string,
  state: DataGridPersistedState,
) {
  if (typeof window === "undefined") {
    return;
  }

  try {
    window.localStorage.setItem(
      dataGridStorageKey(tableId),
      JSON.stringify(state),
    );
  } catch {
    // Ignore quota / private-mode failures.
  }
}

"use client";

import { useState } from "react";
import type { DataGridColumnFilters, DataGridSort } from "../../types";
import { useDataGridColumnFilters } from "../filters/use-data-grid-column-filters";
import { useDataGridSort } from "../sort/use-data-grid-sort";

export type DataGridInitialBehavior = {
  filters?: DataGridColumnFilters;
  sort?: DataGridSort;
  search?: string;
};

export const DEFAULT_DATA_GRID_INITIAL_BEHAVIOR: DataGridInitialBehavior = {
  filters: {},
  sort: null,
  search: "",
};

export function useDataGridInitialBehavior(
  initialBehavior: DataGridInitialBehavior = DEFAULT_DATA_GRID_INITIAL_BEHAVIOR,
) {
  const [search, setSearch] = useState(initialBehavior.search ?? "");
  const sortState = useDataGridSort(initialBehavior.sort ?? null);
  const filterState = useDataGridColumnFilters(initialBehavior.filters ?? {});

  return {
    search,
    setSearch,
    sort: sortState.sort,
    setSort: sortState.setSort,
    columnFilters: filterState.columnFilters,
    setColumnFilters: filterState.setColumnFilters,
  };
}

"use client";

import { useLayoutEffect, useRef, useState } from "react";

const MIN_GRID_HEIGHT = 320;
const VIEWPORT_BOTTOM_INSET = 24;
const ESTIMATED_GRID_HEIGHT = "calc(100dvh - 12rem)";

export type DataGridViewportLayout = {
  top: number;
  left: number;
  width: number;
  height: number;
};

export function useDataGridViewportHeight(enabled = true) {
  const sentinelRef = useRef<HTMLDivElement>(null);
  const [layout, setLayout] = useState<DataGridViewportLayout | null>(null);

  useLayoutEffect(() => {
    if (!enabled) {
      setLayout(null);
      return;
    }

    const sentinel = sentinelRef.current;
    if (!sentinel) return;

    const updateLayout = () => {
      const rect = sentinel.getBoundingClientRect();
      const nextHeight = Math.max(
        MIN_GRID_HEIGHT,
        window.innerHeight - rect.top - VIEWPORT_BOTTOM_INSET,
      );

      setLayout((current) => {
        const next = {
          top: rect.top,
          left: rect.left,
          width: rect.width,
          height: nextHeight,
        };

        if (
          current &&
          current.top === next.top &&
          current.left === next.left &&
          current.width === next.width &&
          current.height === next.height
        ) {
          return current;
        }

        return next;
      });
    };

    updateLayout();

    const resizeObserver = new ResizeObserver(updateLayout);
    resizeObserver.observe(document.documentElement);

    if (sentinel.parentElement) {
      resizeObserver.observe(sentinel.parentElement);
    }

    window.addEventListener("resize", updateLayout);

    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", updateLayout);
    };
  }, [enabled]);

  return {
    sentinelRef,
    layout,
    estimatedHeight: ESTIMATED_GRID_HEIGHT,
  };
}
